  });
  fieldEl.addEventListener('input', function (e) {
    var f = e.target.getAttribute && e.target.getAttribute('data-f');
    if (!f) return;
    // 입력은 원문 그대로 저장하고, LOWER CASE 여부에 따라 표시/내부값을 계산
