const { chromium } = require('C:\\\\Users\\\\gosts\\\\AppData\\\\Roaming\\\\npm\\\\node_modules\\\\playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const ids=Array.from({length:12},(_,i)=>"'`CH15-L${String(i+1).padStart(2,'"'0')}-S01"'`);
 for(const id of ids){
  const p=await browser.newPage({viewport:{width:1000,height:900}}); const errs=[];
  p.on('"'console',m=>{if(m.type()==='error') errs.push('console:'+m.text())}); p.on('pageerror',e=>errs.push('page:'+e.message));
  const resp=await p.goto("'`http://localhost:8141/embeds/abap/${id}.html`,{waitUntil:'"'networkidle',timeout:15000});
  await p.waitForTimeout(200);
  const m=await p.evaluate(()=>({title:document.title,buttons:document.querySelectorAll('button').length,bodyH:document.body.scrollHeight,scrollW:document.documentElement.scrollWidth,clientW:document.documentElement.clientWidth}));
  console.log(JSON.stringify({id,status:resp&&resp.status(),...m,errs}));
  await p.close();
 }
 await browser.close();
})();
'@ | node -"

